import{_ as t,o as a,c as i,a2 as r}from"./chunks/framework.CyZTVJbV.js";const p=JSON.parse('{"title":"kiwa v2.1 released — quality-metrics 深化 IV (adaptive drift threshold learning、 statistical inference SSOT、 47 milestone streak、 4 PR rhythm 復帰、 systematic pattern 44 度目)","description":"","frontmatter":{},"headers":[],"relativePath":"announcements/v2.1/gh-discussions-announcement.md","filePath":"announcements/v2.1/gh-discussions-announcement.md"}'),s={name:"announcements/v2.1/gh-discussions-announcement.md"};function n(o,e,l,h,d,c){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="kiwa-v2-1-released-—-quality-metrics-深化-iv-adaptive-drift-threshold-learning、-statistical-inference-ssot、-47-milestone-streak、-4-pr-rhythm-復帰、-systematic-pattern-44-度目" tabindex="-1">kiwa v2.1 released — quality-metrics 深化 IV (adaptive drift threshold learning、 statistical inference SSOT、 47 milestone streak、 4 PR rhythm 復帰、 systematic pattern 44 度目) <a class="header-anchor" href="#kiwa-v2-1-released-—-quality-metrics-深化-iv-adaptive-drift-threshold-learning、-statistical-inference-ssot、-47-milestone-streak、-4-pr-rhythm-復帰、-systematic-pattern-44-度目" aria-label="Permalink to &quot;kiwa v2.1 released — quality-metrics 深化 IV (adaptive drift threshold learning、 statistical inference SSOT、 47 milestone streak、 4 PR rhythm 復帰、 systematic pattern 44 度目)&quot;">​</a></h1><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>kiwa v2.1 is out。 <strong>quality-metrics 深化 IV</strong> 単軸 milestone、 v0.5 historical trend + v0.6 drift-gate integration → v2.1 で 「driftThresholdPct を 過去 N snapshot から 自動学習」 の adaptive layer を追加。 統計的異常検知 (mean + k*stdev SSOT、 default k=2 = 95% 信頼区間) で per-axis volatility を吸収、 v2.0 rename milestone (5 PR 例外拡張) 後 の <strong>4 PR rhythm 復帰 milestone</strong>、 <strong>systematic pattern 44 度目適用</strong> (statistical inference variant)、 <strong>47 milestone snippet streak 到達</strong>、 shape 契約 preserving 絶対維持、 depth-5 実運用継続 pattern 3 例目 の compound 深化。</p><h2 id="what-s-new" tabindex="-1">What&#39;s new <a class="header-anchor" href="#what-s-new" aria-label="Permalink to &quot;What&#39;s new&quot;">​</a></h2><h3 id="kiwa-lab-quality-metrics-v2-0-→-v2-1-minor-bump" tabindex="-1"><code>@kiwa-lab/quality-metrics</code> v2.0 → v2.1 minor bump <a class="header-anchor" href="#kiwa-lab-quality-metrics-v2-0-→-v2-1-minor-bump" aria-label="Permalink to &quot;`@kiwa-lab/quality-metrics` v2.0 → v2.1 minor bump&quot;">​</a></h3><ul><li><strong><code>learnAdaptiveThreshold</code></strong> = 過去 N snapshot から axis 別 adaptive threshold 学習</li><li><strong><code>pickThresholdForAxis</code></strong> = axis 別 fallback SSOT helper (perAxis 存在 → 個別 / 不在 → aggregate)</li><li><strong><code>AdaptiveThreshold</code> + <code>AdaptiveThresholdReport</code></strong> type SSOT</li><li><strong>統計的異常検知</strong> = mean + k*stdev、 axis 別 独立学習、 baseline=0 Infinity 除外</li><li><strong>shape 契約 preserving 絶対維持</strong> = 既存 API (v0.5 の 4 export + v0.6 の ReleaseGateContext) 変更 0</li></ul><h3 id="dogfood-新規" tabindex="-1">dogfood 新規 <a class="header-anchor" href="#dogfood-新規" aria-label="Permalink to &quot;dogfood 新規&quot;">​</a></h3><ul><li><code>dogfood-quality-metrics-adaptive-threshold-app</code> = 4 pattern workflow (collectRolling + learnFromHistory + evaluateWithLearnedThreshold + explainLearnedGate)、 10 test 全 PASS</li></ul><h3 id="_1-new-tutorial-migration-concept" tabindex="-1">1 new tutorial + migration + concept <a class="header-anchor" href="#_1-new-tutorial-migration-concept" aria-label="Permalink to &quot;1 new tutorial + migration + concept&quot;">​</a></h3><ul><li><strong><a href="https://cardene777.github.io/kiwa/tutorials/128-quality-metrics-adaptive-threshold" target="_blank" rel="noreferrer">Tutorial 128 — quality-metrics v2.1 adaptive threshold</a></strong></li><li>Migration v2.0 → v2.1 additive</li><li>Concept doc <code>quality-metrics-adaptive-threshold.md</code></li></ul><h3 id="_47-milestone-consecutive-snippet-validation-streak" tabindex="-1">47-milestone consecutive snippet validation streak <a class="header-anchor" href="#_47-milestone-consecutive-snippet-validation-streak" aria-label="Permalink to &quot;47-milestone consecutive snippet validation streak&quot;">​</a></h3><p>v1.23 → v2.1 = <strong>47 milestone</strong>、 kiwa 史上最長記録更新継続。</p><h3 id="_4-pr-rhythm-復帰" tabindex="-1">4 PR rhythm 復帰 <a class="header-anchor" href="#_4-pr-rhythm-復帰" aria-label="Permalink to &quot;4 PR rhythm 復帰&quot;">​</a></h3><p>v2.0 rename milestone (5 PR 例外拡張) の 直後、 v2.1 で 4 PR rhythm 復帰、 v1.55-v1.67 の 14 milestone 連続 rhythm を継承 (v2.1 で <strong>15 milestone 目 = 60 PR 連続同 rhythm</strong> ...ただし v2.0 の 5 PR 例外を挟んでいるため rhythm streak は v2.1 で 1 milestone 目 として reset)。</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -D</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @kiwa-lab/quality-metrics@^2.1</span></span></code></pre></div><h2 id="migration-guide" tabindex="-1">Migration guide <a class="header-anchor" href="#migration-guide" aria-label="Permalink to &quot;Migration guide&quot;">​</a></h2><p><a href="https://cardene777.github.io/kiwa/migrations/v2.0-to-v2.1" target="_blank" rel="noreferrer">v2.0 → v2.1</a></p><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><ul><li>v2.2+ = 別 pair の depth-5 拡張 (4 例目 自然 発生 待ち) or quality-metrics v2.2 (multi-baseline comparison or automatic outlier detection)</li></ul>',20)])])}const u=t(s,[["render",n]]);export{p as __pageData,u as default};
